// 2D compressible Euler + gravity (+y), Rayleigh-Taylor. FV: MUSCL(MC, primitive) + HLLC + SSP-RK3.
// usage: ./rt NX NY TEND NOUT outprefix [perturb=1] [limiter: 0 minmod,1 MC]
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#define G 1.4
#define GRAV 1.0
#define NG 2
static int NX, NY, SX, SY; static double dx, dy; static int LIM=1;
#define ID(i,j) ((j)*SX+(i))
static inline double sgn(double a){return a>0?1:(a<0?-1:0);}
static inline double lim(double a,double b){
  if(LIM==0) return (a*b<=0)?0:sgn(a)*fmin(fabs(a),fabs(b));
  if(a*b<=0) return 0; return sgn(a)*fmin(fmin(2*fabs(a),2*fabs(b)),0.5*fabs(a+b));
}
// primitive arrays: r,u,v,p ; conserved U[4]
static void hllc(double rl,double ul,double vl,double pl,double rr,double ur,double vr,double pr,double *f){
  // normal velocity u, tangential v
  double cl=sqrt(G*pl/rl), cr=sqrt(G*pr/rr);
  double El=pl/(G-1)+0.5*rl*(ul*ul+vl*vl), Er=pr/(G-1)+0.5*rr*(ur*ur+vr*vr);
  double SL=fmin(ul-cl,ur-cr), SR=fmax(ul+cl,ur+cr);
  double SM=(pr-pl+rl*ul*(SL-ul)-rr*ur*(SR-ur))/(rl*(SL-ul)-rr*(SR-ur));
  if(SL>=0){f[0]=rl*ul;f[1]=rl*ul*ul+pl;f[2]=rl*ul*vl;f[3]=(El+pl)*ul;return;}
  if(SR<=0){f[0]=rr*ur;f[1]=rr*ur*ur+pr;f[2]=rr*ur*vr;f[3]=(Er+pr)*ur;return;}
  double r,u,v,p,E,S;
  if(SM>=0){r=rl;u=ul;v=vl;p=pl;E=El;S=SL;} else {r=rr;u=ur;v=vr;p=pr;E=Er;S=SR;}
  double fk[4]={r*u,r*u*u+p,r*u*v,(E+p)*u};
  double c=r*(S-u)/(S-SM);
  double us[4]={c,c*SM,c*v,c*(E/r+(SM-u)*(SM+p/(r*(S-u))))};
  double uk[4]={r,r*u,r*v,E};
  for(int k=0;k<4;k++) f[k]=fk[k]+S*(us[k]-uk[k]);
}
static double *W[4]; // primitives incl ghosts
static void fill_prim(double **U){
  #pragma omp parallel for
  for(int j=NG;j<NY+NG;j++) for(int i=NG;i<NX+NG;i++){int id=ID(i,j);
    double r=U[0][id],u=U[1][id]/r,v=U[2][id]/r;
    W[0][id]=r;W[1][id]=u;W[2][id]=v;W[3][id]=(G-1)*(U[3][id]-0.5*r*(u*u+v*v));}
  // periodic x
  for(int j=NG;j<NY+NG;j++) for(int g=0;g<NG;g++) for(int k=0;k<4;k++){
    W[k][ID(g,j)]=W[k][ID(NX+g,j)]; W[k][ID(NX+NG+g,j)]=W[k][ID(NG+g,j)];}
  // reflective y with hydrostatic pressure extrapolation
  for(int i=0;i<SX;i++) for(int g=0;g<NG;g++){
    int jg=NG-1-g, jm=NG+g; double r=W[0][ID(i,jm)];
    W[0][ID(i,jg)]=r; W[1][ID(i,jg)]=W[1][ID(i,jm)]; W[2][ID(i,jg)]=-W[2][ID(i,jm)];
    W[3][ID(i,jg)]=W[3][ID(i,jm)]-r*GRAV*(2*g+1)*dy;
    jg=NY+NG+g; jm=NY+NG-1-g; r=W[0][ID(i,jm)];
    W[0][ID(i,jg)]=r; W[1][ID(i,jg)]=W[1][ID(i,jm)]; W[2][ID(i,jg)]=-W[2][ID(i,jm)];
    W[3][ID(i,jg)]=W[3][ID(i,jm)]+r*GRAV*(2*g+1)*dy;}
}
static double *FX[4],*FY[4];
static void rhs(double **U,double **R){
  fill_prim(U);
  #pragma omp parallel for
  for(int j=NG;j<NY+NG;j++) for(int i=NG-1;i<NX+NG;i++){ // face i+1/2
    double L[4],Rr[4],f[4];
    for(int k=0;k<4;k++){double *w=W[k];
      double sl=lim(w[ID(i,j)]-w[ID(i-1,j)],w[ID(i+1,j)]-w[ID(i,j)]);
      double sr=lim(w[ID(i+1,j)]-w[ID(i,j)],w[ID(i+2,j)]-w[ID(i+1,j)]);
      L[k]=w[ID(i,j)]+0.5*sl; Rr[k]=w[ID(i+1,j)]-0.5*sr;}
    hllc(L[0],L[1],L[2],L[3],Rr[0],Rr[1],Rr[2],Rr[3],f);
    for(int k=0;k<4;k++) FX[k][ID(i,j)]=f[k];}
  #pragma omp parallel for
  for(int j=NG-1;j<NY+NG;j++) for(int i=NG;i<NX+NG;i++){ // face j+1/2
    double L[4],Rr[4],f[4];
    for(int k=0;k<4;k++){double *w=W[k];
      // hydrostatic-aware reconstruction for p: limit deviation from rho*g gradient
      double a=w[ID(i,j)]-w[ID(i,j-1)], b=w[ID(i,j+1)]-w[ID(i,j)];
      double c=w[ID(i,j+2)]-w[ID(i,j+1)];
      double sl,sr;
      if(k==3){double h0=W[0][ID(i,j)]*GRAV*dy, h1=W[0][ID(i,j+1)]*GRAV*dy;
        sl=h0+lim(a-h0,b-h0); sr=h1+lim(b-h1,c-h1);}
      else {sl=lim(a,b); sr=lim(b,c);}
      L[k]=w[ID(i,j)]+0.5*sl; Rr[k]=w[ID(i,j+1)]-0.5*sr;}
    if(j==NG-1){ Rr[2]=0; L[2]=0; }      // walls: exact zero normal velocity
    if(j==NY+NG-1){ Rr[2]=0; L[2]=0; }
    hllc(L[0],L[2],L[1],L[3],Rr[0],Rr[2],Rr[1],Rr[3],f); // normal=v
    FY[0][ID(i,j)]=f[0]; FY[1][ID(i,j)]=f[2]; FY[2][ID(i,j)]=f[1]; FY[3][ID(i,j)]=f[3];}
  #pragma omp parallel for
  for(int j=NG;j<NY+NG;j++) for(int i=NG;i<NX+NG;i++){int id=ID(i,j);
    for(int k=0;k<4;k++) R[k][id]=-(FX[k][id]-FX[k][ID(i-1,j)])/dx-(FY[k][id]-FY[k][ID(i,j-1)])/dy;
    R[2][id]+=U[0][id]*GRAV;           // +y gravity on momentum
    // energy source: g * (mass flux), averaged face mass flux (better balanced than rho*v)
    R[3][id]+=GRAV*0.5*(FY[0][id]+FY[0][ID(i,j-1)]);
  }
}
static double maxspeed(double **U){double m=0;
  #pragma omp parallel for reduction(max:m)
  for(int j=NG;j<NY+NG;j++) for(int i=NG;i<NX+NG;i++){int id=ID(i,j);
    double r=U[0][id],u=U[1][id]/r,v=U[2][id]/r,p=(G-1)*(U[3][id]-0.5*r*(u*u+v*v));
    double c=sqrt(G*p/r); double s=fmax((fabs(u)+c)/dx,(fabs(v)+c)/dy); if(s>m)m=s;}
  return m;}
int main(int argc,char**argv){
  NX=atoi(argv[1]);NY=atoi(argv[2]);double TEND=atof(argv[3]);int NOUT=atoi(argv[4]);char*pre=argv[5];
  int pert=argc>6?atoi(argv[6]):1; if(argc>7) LIM=atoi(argv[7]);
  SX=NX+2*NG;SY=NY+2*NG;dx=0.25/NX;dy=1.0/NY;size_t N=(size_t)SX*SY;
  double *U[4],*U1[4],*U2[4],*R[4];
  for(int k=0;k<4;k++){U[k]=calloc(N,8);U1[k]=calloc(N,8);U2[k]=calloc(N,8);R[k]=calloc(N,8);W[k]=calloc(N,8);FX[k]=calloc(N,8);FY[k]=calloc(N,8);}
  // IC: cell averages via 4x4 Gauss-Legendre quadrature of conserved vars
  double gq[4]={-0.8611363115940526,-0.3399810435848563,0.3399810435848563,0.8611363115940526};
  double gw[4]={0.3478548451374538,0.6521451548625461,0.6521451548625461,0.3478548451374538};
  for(int j=NG;j<NY+NG;j++) for(int i=NG;i<NX+NG;i++){
    double s[4]={0,0,0,0};
    for(int a=0;a<4;a++)for(int b=0;b<4;b++){
      double x=(i-NG+0.5+0.5*gq[a])*dx,y=(j-NG+0.5+0.5*gq[b])*dy,w=gw[a]*gw[b]/4;
      double r=2.0+(1.0-2.0)*0.5*(1+tanh(50*(y-0.5)));
      double p=y<0.5?2*y+1:y+1.5; double c=sqrt(G*p/r);
      double v=pert?-0.025*c*cos(8*M_PI*x)*pow(sin(M_PI*y),6):0;
      s[0]+=w*r;s[1]+=0;s[2]+=w*r*v;s[3]+=w*(p/(G-1)+0.5*r*v*v);}
    for(int k=0;k<4;k++)U[k][ID(i,j)]=s[k];}
  double t=0;int step=0,iout=0;char fn[512];
  FILE*fd; sprintf(fn,"%s_diag.txt",pre); fd=fopen(fn,"w");
  while(1){
    // diagnostics
    double M=0,E=0,KE=0,KEy=0,vmax=0;
    for(int j=NG;j<NY+NG;j++)for(int i=NG;i<NX+NG;i++){int id=ID(i,j);double y=(j-NG+0.5)*dy;
      M+=U[0][id];E+=U[3][id]-U[0][id]*GRAV*y;double ke=0.5*(U[1][id]*U[1][id]+U[2][id]*U[2][id])/U[0][id];KE+=ke;
      KEy+=0.5*U[2][id]*U[2][id]/U[0][id];double vv=fabs(U[2][id]/U[0][id]);if(vv>vmax)vmax=vv;}
    fprintf(fd,"%.6f %.15e %.15e %.10e %.10e %.10e\n",t,M*dx*dy,E*dx*dy,KE*dx*dy,KEy*dx*dy,vmax);
    if(t>=iout*TEND/NOUT-1e-12){
      sprintf(fn,"%s_%03d.bin",pre,iout);FILE*f=fopen(fn,"wb");fwrite(&t,8,1,f);
      for(int k=0;k<4;k++)for(int j=NG;j<NY+NG;j++)fwrite(&U[k][ID(NG,j)],8,NX,f);fclose(f);
      fprintf(stderr,"out %d t=%.4f step=%d M=%.12f E=%.12f KE=%.3e\n",iout,t,step,M*dx*dy,E*dx*dy,KE*dx*dy);iout++;}
    if(t>=TEND-1e-12)break;
    double dt=0.4/maxspeed(U); double tn=iout*TEND/NOUT; if(t+dt>tn)dt=tn-t;
    rhs(U,R);
    for(int k=0;k<4;k++)for(size_t n=0;n<N;n++)U1[k][n]=U[k][n]+dt*R[k][n];
    rhs(U1,R);
    for(int k=0;k<4;k++)for(size_t n=0;n<N;n++)U2[k][n]=0.75*U[k][n]+0.25*(U1[k][n]+dt*R[k][n]);
    rhs(U2,R);
    for(int k=0;k<4;k++)for(size_t n=0;n<N;n++)U[k][n]=U[k][n]/3+2.0/3*(U2[k][n]+dt*R[k][n]);
    t+=dt;step++;
  }
  fclose(fd);return 0;}
EOF
